pipeline {
    agent any

    environment {
        REMOTE_HOST = '20.48.1.66' // 远程服务器地址
        REMOTE_USER = 'root' // 远程服务器用户名
        REMOTE_CREDENTIALS_ID = 'server-18-credentials-id' // Jenkins中保存的远程服务器SSH凭证ID
        REMOTE_ADDRESS = '/data/soft/sxglpt/'  //远程服务器web文件地址
        TIMESTAMP = new Date().format("yyyyMMddHHmmss", TimeZone.getTimeZone('UTC+8'))
    }

    stages {
        stage('Git') {
            steps {
                echo "Trying to checkout code from gitlab branch: ${params.Branch}"
                checkout scmGit(branches: [[name: "${params.Branch}"]], extensions: [], userRemoteConfigs: [[credentialsId: 'SSH-KEY-FOR-GITLAB', url: '${GIALAB_ADDRESS}/front/other/matter-management-platform-web']])
            }
        }

        stage('Npm Install') {
            steps {
                //  nvm("v20.13.1") {
                    sh 'node -v'
                    sh 'pnpm -v'
                    sh 'pnpm install --no-frozen-lockfile'
                // }


            }
        }

        stage('Npm Build') {
            steps {
        //         // sh 'npm run build'
        //         nvm("v18.20.2") {
                    sh 'pnpm run build:dev'
        //         }

            }
        }


        stage('Deploy to Remote') {
            steps {
                script {
                    sh 'pwd'
                    sh 'tar -zcvf ./dist.tar.gz ./dist'
                    sh 'scp dist.tar.gz root@${REMOTE_HOST}:${REMOTE_ADDRESS} ' 

                    sshagent([REMOTE_CREDENTIALS_ID]) {
                        sh """
                            ssh ${REMOTE_USER}@${REMOTE_HOST} '
                            cd ${REMOTE_ADDRESS}  &&

                            if [ -d "dist/" ];then
                                mv dist/ dist-${TIMESTAMP}/
                            fi  &&
                            tar -zxvf dist.tar.gz  &&
                            rm -f dist.tar.gz
                            '
                           """
                    }
                }
            }
        }


    }
}
